import { fetchAzureKeyVaultSecrets } from './index';

// The Azure SDKs are mocked so these tests exercise only the enabled/disabled secret iteration,
// with no real network or credential work.
jest.mock('@azure/identity');
jest.mock('@azure/keyvault-secrets');

const { SecretClient } = require('@azure/keyvault-secrets');

describe('Azure Key Vault - skip disabled secrets', () => {
  let mockSecretClient: any;

  beforeEach(() => {
    jest.clearAllMocks();
    mockSecretClient = {
      listPropertiesOfSecrets: jest.fn(),
      getSecret: jest.fn()
    };
    SecretClient.mockImplementation(() => mockSecretClient);
  });

  const azureConfig = { tenantId: 'test-tenant', clientId: 'test-client', clientSecret: 'test-secret' };

  it('should skip disabled secrets and only fetch enabled ones', async () => {
    const properties = [
      { name: 'enabled-secret-1', enabled: true },
      { name: 'disabled-secret-1', enabled: false },
      { name: 'enabled-secret-2', enabled: true },
      { name: 'disabled-secret-2', enabled: false }
    ];
    mockSecretClient.listPropertiesOfSecrets.mockImplementation(async function* () {
      for (const prop of properties) yield prop;
    });
    mockSecretClient.getSecret
      .mockResolvedValueOnce({ value: 'value-for-enabled-1' })
      .mockResolvedValueOnce({ value: 'value-for-enabled-2' });

    const result = await fetchAzureKeyVaultSecrets({ azureConfig, vaultNames: ['test-vault'] });

    expect(result[0].data).toEqual({
      'enabled-secret-1': 'value-for-enabled-1',
      'enabled-secret-2': 'value-for-enabled-2'
    });
    expect(mockSecretClient.getSecret).toHaveBeenCalledTimes(2);
    expect(mockSecretClient.getSecret).toHaveBeenCalledWith('enabled-secret-1');
    expect(mockSecretClient.getSecret).toHaveBeenCalledWith('enabled-secret-2');
    expect(mockSecretClient.getSecret).not.toHaveBeenCalledWith('disabled-secret-1');
    expect(mockSecretClient.getSecret).not.toHaveBeenCalledWith('disabled-secret-2');
  });

  it('should work the same way with the Azure CLI credential', async () => {
    const properties = [
      { name: 'cli-enabled-secret', enabled: true },
      { name: 'cli-disabled-secret', enabled: false }
    ];
    mockSecretClient.listPropertiesOfSecrets.mockImplementation(async function* () {
      for (const prop of properties) yield prop;
    });
    mockSecretClient.getSecret.mockResolvedValueOnce({ value: 'cli-secret-value' });

    const result = await fetchAzureKeyVaultSecrets({ vaultNames: ['test-vault'], useCLI: true });

    expect(result[0].data).toEqual({ 'cli-enabled-secret': 'cli-secret-value' });
    expect(mockSecretClient.getSecret).toHaveBeenCalledTimes(1);
    expect(mockSecretClient.getSecret).toHaveBeenCalledWith('cli-enabled-secret');
    expect(mockSecretClient.getSecret).not.toHaveBeenCalledWith('cli-disabled-secret');
  });
});

describe('Azure Key Vault - vault name validation', () => {
  let mockSecretClient: any;

  beforeEach(() => {
    jest.clearAllMocks();
    mockSecretClient = {
      listPropertiesOfSecrets: jest.fn().mockImplementation(async function* () {}),
      getSecret: jest.fn()
    };
    SecretClient.mockImplementation(() => mockSecretClient);
  });

  const azureConfig = { tenantId: 'test-tenant', clientId: 'test-client', clientSecret: 'test-secret' };

  // A vault name is concatenated into `https://<name>.vault.azure.net`; any of these would either
  // reroute the request (URL metacharacters) or is simply not a valid Azure Key Vault name.
  it.each([
    ['reroutes host via fragment', 'evil.com#'],
    ['reroutes host via path', 'foo/../bar'],
    ['contains a colon', 'vault:name'],
    ['contains a query', 'vault?x=1'],
    ['contains a space', 'has space'],
    ['starts with a digit', '1abc'],
    ['starts with a hyphen', '-lead'],
    ['ends with a hyphen', 'trail-'],
    ['has consecutive hyphens', 'a--b'],
    ['is shorter than 3 chars', 'ab'],
    ['is longer than 24 chars', 'a' + 'b'.repeat(24)]
  ])('rejects a vault name that %s', async (_label, vaultName) => {
    const result = await fetchAzureKeyVaultSecrets({ azureConfig, vaultNames: [vaultName] });

    expect(result).toEqual([{ vaultName, error: 'Invalid Azure Key Vault name' }]);
    expect(SecretClient).not.toHaveBeenCalled();
  });

  it.each([
    ['a minimum-length name', 'abc'],
    ['a maximum-length name', 'a' + 'b'.repeat(23)],
    ['a hyphenated name', 'my-vault-1']
  ])('accepts %s and fetches its secrets', async (_label, vaultName) => {
    const result = await fetchAzureKeyVaultSecrets({ azureConfig, vaultNames: [vaultName] });

    expect(result).toEqual([{ vaultName, data: {} }]);
    expect(SecretClient).toHaveBeenCalledTimes(1);
  });

  it('rejects only the invalid names while still fetching the valid ones', async () => {
    const result = await fetchAzureKeyVaultSecrets({ azureConfig, vaultNames: ['good-vault', 'evil.com#'] });

    expect(result).toEqual([
      { vaultName: 'good-vault', data: {} },
      { vaultName: 'evil.com#', error: 'Invalid Azure Key Vault name' }
    ]);
    expect(SecretClient).toHaveBeenCalledTimes(1);
  });
});
